mapper.select:
select `ar1`.`id`, `ar1`.`event_id`, `ar1`.`proposer_id`, `ar1`.`apply_reason`, `ar1`.`apply_type`, `ar1`.`approver_id`, `ar1`.`approve_reason`, `ar1`.`approve_time`, `ar1`.`dead_time`, `ar1`.`status`, `ar1`.`upd_time`, `ar1`.`crt_time` from `approval_record` `ar1` where 1 > ( select count(*) from `approval_record` where `event_id` = `ar1`.`event_id` and `crt_time` > `ar1`.`crt_time` and `event_type` = #{eventType})
and `ar1`.`crt_id` = #{loginUserId}
and `ar1`.`approver_id` = #{loginUserId}
and `ar1`.`event_type` = #{eventType}
and `ar1`.`event_id` in
#{item}
and to_days(`ar1`.`crt_time`) = to_days(#{submitTime})
order by
`ar1`.`status` asc, `ar1`.`crt_time` desc
`ar1`.`status` desc, `ar1`.`crt_time` desc
FIELD(`ar1`.`status`,1,2,0), `ar1`.`crt_time` desc
